mapper.select:
SELECT
FROM inboundRequests ir JOIN inboundItems ii ON ir.inReqId = ii.inReqId JOIN coffee c ON ii.cfId = c.cfId
ir.managerId = #{userId}
ir.comId = #{userId}
AND ii.status LIKE CONCAT('%', #{criteria.keyword}, '%')
AND c.cfCategory LIKE CONCAT('%', #{criteria.keyword}, '%')
AND c.cfName LIKE CONCAT('%', #{criteria.keyword}, '%')
ORDER BY ir.inDttmReq DESC LIMIT #{criteria.amount} OFFSET #{criteria.skip}
